    @Test
    fun testCorlaPRNGcounty() {
        val verbose = true
        var countMiss = 0
        var countExtra = 0
        // val county = "Gilpin" // Cheyenne, Crowley, Gilpin (1 mvr not in prn)
        val stateInput = Statewide2020General()
        val county = "Morgan"
        // stateInput.counties().forEach { county ->
            println("-------------- $county")
            val ccmvrs = stateInput.cardComparison().mvrs.filter { it.county() == county }
            val ccidSet = ccmvrs.map { "${it.county()}: ${it.imprintedId()}" }.toSet()
            val ccIds = ccmvrs.map { it.imprintedId() }.toSet()
            if (verbose) println("  ccmvrs size=${ccmvrs.size} unique=${ccidSet.size} ccids=${ccIds.toSet().size}")

            //ccIds.sorted().forEach { println("  ${it}") }
            //println()

            val strata = stateInput.countyStrataMap[county]!!
            val countyManifest = stateInput.countyManifest(county)!!
            // modulus max - min + 1 = 1_444_047
            val corlaPRNG = CorlaPRNG(seed2020, false, 1, strata.ballotCardCount) // without replacement (!)
            if (verbose) println("  county population=${strata.ballotCardCount} nmvrs =${strata.nmvrs}")

            val prns = corlaPRNG.getRandomNumbers(0, strata.nmvrs - 1)
            if (verbose) println("  prns size=${prns.size} unique=${prns.toSet().size}")

            val prnIds = prns.map { prn -> countyManifest.idFromIndex(prn) }
            val prnIdSet = prnIds.toSet()
            if (verbose) println("  ids size=${prnIds.size} unique=${prnIdSet.size}")

            println("\n  who is in prnIds not in ccidSet?")
            var countyMiss = 0
            prnIds.forEachIndexed { idx, id ->
                print("$idx: ${prns[idx]} -> $id ")
                if (!ccidSet.contains(id)) {
                    // println("    $idx: ${prns[idx]} -> $id *** MISS")
                    println(" *** MISS")
                    countMiss++
                    countyMiss++
                } else println()
            }

            val diffSet = ccidSet - prnIds
            if (diffSet.isNotEmpty()) {
                println("\n  who is in ccidSet not in prnIds?")
                diffSet.forEach { println("    $it") }
                countExtra += diffSet.size
            }
            println("countyMiss = $countyMiss countyExtra = ${diffSet.size}")
        // }

        println("countMiss = $countMiss countExtra = $countExtra")
    }

    @Test
    fun testCorlaPRNGstatewide() {
        val population = 4_114_582
        val statewideNmvrs = 953
        // manifest.totalCards=4125914, subtract Gunnison 11322 = 4_114_592

        var stateHits = 0
        var countyHits = 0
        var countMiss = 0

        val stateInput = Statewide2020General()
        val allMvrs: List<ComparisonMvr> = stateInput.cardComparison().mvrs

        val countyMap = stateInput.counties().filter{ it != "Gunnison"}.map { county -> CorlaPRNGcounty(stateInput, county) }.associateBy { it.county }
        val countyMap2 = stateInput.counties().filter{ it != "Gunnison"}.map { county -> CorlaPrngCounty(stateInput, county) }.associateBy { it.county }
        val countyNmvrs = countyMap.map{ it.value.countyMvrs }.sum()
        val expectStateNmvrs = allMvrs.size - countyNmvrs
        // println("expectStateNmvrs=$expectStateNmvrs")

        val statewide = CorlaPRNGstatewide(stateInput, population = population, statewideNmvrs = statewideNmvrs)

        val allPrnIds = mutableSetOf<String>()
        allPrnIds.addAll(statewide.prnIdSet)
        countyMap.values.forEach {
            allPrnIds.addAll(it.prnIdSet)
        }
        println("  unique PrnIds=${allPrnIds.size}")

        val allMvrIds = mutableSetOf<String>()
        allMvrs.forEach { mvr ->
            allMvrIds.add("${mvr.county()}: ${mvr.imprintedId()}")
        }
        println("  mvrs=${allMvrs.size} unique MvrIds=${allMvrIds.size}")

        //    println("-------------- $county")
        var count = 0
        allMvrs.forEach { mvr ->
            val id = "${mvr.county()}: ${mvr.imprintedId()}"
            if (statewide.claim(id, mvr)) {
                stateHits++
            } else {
                val county = countyMap[mvr.county()]!!
                if (county.claim(id, mvr)) {
                    countyHits++
                    val county2 = countyMap2[mvr.county()]!!
                    if (!county2.claim(id, mvr)) {
                        println("($count) countyMap2 != countyMap $id db=${mvr.dbId}")
                    }

                } else {
                    if (allPrnIds.contains(id))
                        println("($count) allPrnIds has $id db=${mvr.dbId}")
                    else
                        println("($count) MISS $id db=${mvr.dbId}")
                    countMiss++
                }
            }
            count++
        }
        println()
        println("statewideNmvrs (guess) = ${statewideNmvrs}")
        println("allMvrs = ${allMvrs.size}")
        println("countyNmvrs.sum()=$countyNmvrs")

        println("countyHits = $countyHits")
        println("stateHits = $stateHits")
        println("allHits = ${countyHits + stateHits}")
        println("countMiss = $countMiss")
    }

    inner class CorlaPRNGstatewide(val stateInput: StatewideInput, val population: Int = 4_114_582, val statewideNmvrs: Int = 1000, val verbose: Boolean = false) {
        val prnIds: List<String>
        val prnIdSet: Set<String>
        init {
            val corlaPRNG = CorlaPRNG(seed2020, false, 1, population) // without replacement (!)

            val prns = corlaPRNG.getRandomNumbers(0, statewideNmvrs - 1)

            val manifest = stateInput.statewideManifest()
            println("  manifest.totalCards=${manifest.totalCards}")

            prnIds = prns.map { prn -> manifest.idFromIndex(prn) }
            prnIdSet = prnIds.toSet()
            if (verbose) println("  ids size=${prnIds.size} unique=${prnIdSet.size}")
        }

        fun claim(id: String, mvr: ComparisonMvr): Boolean {
            return prnIdSet.contains(id)
        }
    }

    @Test
    fun testCorlaPrngStatewide() {
        val population = 4_114_582
        val statewideNmvrs = 953
        var countMiss = 0

        val stateInput = Statewide2020General()
        val allMvrs: List<ComparisonMvr> = stateInput.cardComparison().mvrs

        val countyMap = stateInput.counties().filter{ it != "Gunnison"}.map { county -> CorlaPrngCounty(stateInput, county) }.associateBy { it.county }
        val countyNmvrs = countyMap.map{ it.value.countyMvrs }.sum()

        val prngs = CorlaPrngStatewide(stateInput, population = population, statewideNmvrs = statewideNmvrs)
        val sortedPrnIds = prngs.prnIds.sortedBy{ it. first }
        println("  unique PrnIds=${prngs.prnIdSet.size}")

        val allMvrIds = mutableSetOf<String>()
        allMvrs.forEach { mvr ->
            allMvrIds.add("${mvr.county()}: ${mvr.imprintedId()}")
        }
        println("  mvrs=${allMvrs.size} unique MvrIds=${allMvrIds.size}")

        // sort by index, see where it starts to fail - thats where the manifest is wrong
        var count = 0
        sortedPrnIds.forEach { (prn, id) ->
            print("  ($prn): $id")
            if (!allMvrIds.contains(id)) {
                println(" *** MISS")
                countMiss++
            } else println()
            count++
        }
        println()
        println("countMiss = $countMiss")
    }

    class CorlaPrngStatewide(val stateInput: StatewideInput, val population: Int, val statewideNmvrs: Int, val verbose: Boolean = false) {
        val prnIds: List<Pair<Int, String>>
        val prnIdSet: Set<String>

        init {
            val prng = CorlaPrng(stateInput.seed, 1, population) // without replacement (!)

            val prns = mutableListOf<Int>()
            repeat(statewideNmvrs) { prns.add(prng.next()) }
            if (verbose) println("  prns size=${prns.size} unique=${prns.toSet().size}")

            val manifest = stateInput.statewideManifest()
            println("  manifest.totalCards=${manifest.totalCards}")

            prnIds = prns.map { prn -> Pair(prn, manifest.idFromIndex(prn)) }
            prnIdSet = prns.map { prn -> manifest.idFromIndex(prn) }.toSet()
            if (verbose) println("  ids size=${prnIds.size} unique=${prnIdSet.size}")
        }

        fun claim(id: String): Boolean {
            return prnIdSet.contains(id)
        }
    }

    inner class CorlaPRNGcounty(stateInput: StatewideInput, val county: String, verbose: Boolean = false) {
        val prnIds: List<String>
        val prnIdSet: Set<String>
        val countyMvrs: Int

        init {
            println("-------------- $county")
            val strata = stateInput.countyStrataMap[county]!!
            val countyManifest = stateInput.countyManifest(county)!!
            // modulus max - min + 1 = 1_444_047
            val corlaPRNG = CorlaPRNG(seed2020, false, 1, strata.ballotCardCount) // without replacement (!)
            if (verbose) println("  county population=${strata.ballotCardCount} nmvrs =${strata.countyMvrs}") // 2020 doesnt know which are statewide
            countyMvrs = strata.countyMvrs

            val prns = corlaPRNG.getRandomNumbers(0, strata.nmvrs - 1)
            if (verbose) println("  prns size=${prns.size} unique=${prns.toSet().size}")

            prnIds = prns.map { prn -> countyManifest.idFromIndex(prn) }
            prnIdSet = prnIds.toSet()
            if (verbose) println("  ids size=${prnIds.size} unique=${prnIdSet.size}")
        }

        fun claim(id: String, mvr: ComparisonMvr): Boolean {
            return prnIdSet.contains(id)
        }
    }

    inner class CorlaPrngCounty(stateInput: StatewideInput, val county: String, verbose: Boolean = false) {
        val prnIds: List<String>
        val prnIdSet: Set<String>
        val countyMvrs: Int

        init {
            println("-------------- $county")
            val strata = stateInput.countyStrataMap[county]!!
            val countyManifest = stateInput.countyManifest(county)!!
            // modulus max - min + 1 = 1_444_047
            val prng = CorlaPrng(seed2020, 1, strata.ballotCardCount) // without replacement (!)
            if (verbose) println("  county population=${strata.ballotCardCount} nmvrs =${strata.countyMvrs}") // 2020 doesnt know which are statewide
            countyMvrs = strata.countyMvrs

            val prns = mutableListOf<Int>()
            repeat(strata.nmvrs) { prns.add(prng.next()) }
            if (verbose) println("  prns size=${prns.size} unique=${prns.toSet().size}")

            prnIds = prns.map { prn -> countyManifest.idFromIndex(prn, 0) }
            prnIdSet = prnIds.toSet()
            if (verbose) println("  ids size=${prnIds.size} unique=${prnIdSet.size}")
        }

        fun claim(id: String, mvr: ComparisonMvr): Boolean {
            return prnIdSet.contains(id)
        }
    }

